def solve():
    # Nodes 0 to 41
    adj = [0] * 42

    # Difference 1
    for i in range(41):
        adj[i] |= (1 << (i + 1))
        adj[i+1] |= (1 << i)

    # Difference 21
    for i in range(21):
        adj[i] |= (1 << (i + 21))
        adj[i+21] |= (1 << i)

    memo = {}
    def count_is(mask):
        if mask == 0:
            return 1
        if mask in memo:
            return memo[mask]

        # Find the node with the smallest degree
        v = -1
        min_deg = 43
        for i in range(42):
            if (mask >> i) & 1:
                deg = bin(adj[i] & mask).count('1')
                if deg < min_deg:
                    min_deg = deg
                    v = i

        res = count_is(mask & ~(1 << v)) + \
               count_is(mask & ~(1 << v) & ~adj[v])

        memo[mask] = res
        return res

    initial_mask = (1 << 42) - 1
    print(count_is(initial_mask))

solve()

