    # Numbers: 1, 2, 3, 4. Differences: 1, 2
    n = 4
    diff1 = 1
    diff2 = 2
    adj = [0] * n
    for i in range(n):
        for j in range(n):
            if i != j and abs(i - j) == diff1 or abs(i - j) == diff2:
                adj[i] |= (1 << j)

    memo = {}
    def count_is(mask):
        if mask == 0:
            return 1
