        min_deg = n + 1
        for i in range(n):
            if (mask >> i) & 1:
                deg = bin(adj[i] & mask).count('1')
                if deg < min_deg:
                    min_deg = deg
                    v = i
        res = count_is(mask & ~(1 << v)) + \
               count_is(mask & ~(1 << v) & ~adj[v])
        memo[mask] = res
        return res

    print(count_is((1 << n) - 1))

