def find_independent_sets_count(N):
    """
    Calculates the number of independent sets in the graph G_N.
    Vertices are 1 to N. Edges exist if difference is 1 or N/2 (if N is even).
    """
    if N == 0:
        return 1  # Empty set is 1 way
    if N == 1:
        return 2  # {}, {1}

    # 1. Build Adjacency List
    adj = {i: set() for i in range(1, N + 1)}

    # Difference 1 edges
    for i in range(1, N):
        adj[i].add(i+1)
        adj[i+1].add(i)

    # Difference N/2 edges (only if N is even)
    if N % 2 == 0:
        k = N // 2
        for i in range(1, N - k + 1):
            adj[i].add(i + k)
            adj[i + k].add(i)

    # 2. Find all Independent Sets (Brute Force using recursion/bitmask if N small)

    # Since N is very small (<= 6), we iterate through all 2^N subsets
    count = 0
    for i in range(1 << N):
        subset = []
        for j in range(N):
            if (i >> j) & 1:
                subset.append(j + 1)

        is_independent = True
        # Check all pairs in the subset
        for idx1 in range(len(subset)):
            for idx2 in range(idx1 + 1, len(subset)):
                u = subset[idx1]
                v = subset[idx2]

                if v in adj[u]:
                    is_independent = False
                    break
            if not is_independent:
                break

        if is_independent:
            count += 1

    return count

