def count_independent_sets_fast(adj, nodes):
    memo = {}

    def solve(current_nodes):
        if not current_nodes:
            return 1
        if current_nodes in memo:
            return memo[current_nodes]

        # Pick the node with the highest degree in the current subgraph
        v = max(current_nodes, key=lambda x: len([n for n in adj[x] if n in current_nodes]))

        # Option 1: v is NOT in the independent set
        res = solve(tuple(sorted(n for n in current_nodes if n != v)))

        # Option 2: v IS in the independent set
        neighbors_of_v = set(adj[v])
        remaining_nodes = tuple(sorted(n for n in current_nodes if n != v and n not in neighbors_of_v))
        res += solve(remaining_nodes)

        memo[current_nodes] = res
        return res

    return solve(tuple(sorted(nodes)))

